import test from 'node:test';import assert from 'node:assert/strict';import {initialState,reduce,available} from './dist/economy.js';
function play(basket){let s=initialState();for(const a of [{type:'basket',value:basket},{type:'buy-grocery'},{type:'pay-utility'}])s=reduce(s,a);return s;}
test('Branch A preserves goal and protected bills',()=>{let s=play('pantry');assert.equal(available(s),90);s=reduce(s,{type:'pay-repair'});assert.deepEqual([s.cash,s.bills,s.goal,available(s)],[230,180,50,0]);});
test('Branch B rejects repair before allocation adjustment',()=>{let s=play('convenience');const blocked=reduce(s,{type:'pay-repair'});assert.equal(blocked.cash,300);assert.equal(blocked.transactions.length,2);assert.match(blocked.notice,/20/);s=reduce(s,{type:'revise-goal'});assert.equal(s.cash,300);s=reduce(s,{type:'pay-repair'});assert.deepEqual([s.cash,s.bills,s.goal,available(s)],[210,180,30,0]);});
test('Back navigation cannot duplicate charges, rewards or purchases',()=>{let s=reduce(play('pantry'),{type:'pay-repair'});s=reduce(s,{type:'claim-reward'});for(const type of ['buy-grocery','pay-utility','pay-repair','claim-reward'])s=reduce(s,{type});assert.deepEqual([s.cash,s.coins,s.gems,s.transactions.length],[230,100,5,3]);s=reduce(s,{type:'buy-item',value:'decal'});s=reduce(s,{type:'buy-item',value:'decal'});assert.equal(s.coins,40);assert.equal(s.cash,230);s=reduce(s,{type:'buy-item',value:'paint'});assert.equal(s.gems,5);assert.equal(s.owned.length,1);});
test('Hiring is separate, idempotent and cancellation refunds once',()=>{let s=initialState();s=reduce(s,{type:'hire'});s=reduce(s,{type:'hire'});assert.equal(s.helper.cash,100);assert.equal(s.cash,500);s=reduce(s,{type:'cancel-help'});s=reduce(s,{type:'cancel-help'});assert.equal(s.helper.cash,110);});
test('Invalid selections and incomplete sequence cannot spend or earn',()=>{let s=initialState();for(const a of [{type:'buy-grocery'},{type:'pay-utility'},{type:'pay-repair'},{type:'claim-reward'},{type:'equip',value:'decal'},{type:'basket',value:'unknown'}]){const n=reduce(s,a);assert.equal(n.cash,500);assert.equal(n.coins,0);assert.ok(n.notice);}});
test('Reset restores all seed values and ownership',()=>{let s=reduce(play('pantry'),{type:'pay-repair'});s=reduce(s,{type:'claim-reward'});s=reduce(s,{type:'buy-item',value:'decal'});s=reduce(s,{type:'equip',value:'decal'});assert.deepEqual(reduce(s,{type:'reset'}),initialState());});
